import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  if (config.scenePosition) root.position.fromArray(config.scenePosition);
  if (config.sceneRotation) root.rotation.fromArray(config.sceneRotation);
  if (config.sceneScale) root.scale.fromArray(config.sceneScale);

  // Load and normalize watch mesh
  const watchGlb = ctx.glbLoader('/prism-mock/orrery/meshes/watch.glb');
  const watch = watchGlb.scene.clone();

  const bbox = new THREE.Box3().setFromObject(watch);
  const height = bbox.max.y - bbox.min.y;
  watch.scale.multiplyScalar(2.2 / height);

  bbox.setFromObject(watch);
  const center = new THREE.Vector3();
  bbox.getCenter(center);
  watch.position.sub(center);

  // Apply PBR materials
  watch.traverse((child) => {
    if (child.isMesh && child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        if (m.isMeshStandardMaterial) {
          m.roughness = 0.52;
          m.metalness = 0.55;
          m.clearcoat = 0.2;
          m.clearcoatRoughness = 0.4;
          m.anisotropy = 0.8;
        }
      });
    }
  });

  // Plinth cylinder
  const plinthGeom = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new THREE.MeshStandardMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeom, plinthMat);
  plinth.position.y = -1.225;

  // Backdrop with engineered gradient
  const gw = 256, gh = 256;
  const gdata = new Uint8Array(gw * gh * 4);
  for (let y = 0; y < gh; y++) {
    const t = y / gh;
    let r, g, b;
    if (t < 0.55) {
      const s = t / 0.55;
      r = Math.round(0x0b + (0x10 - 0x0b) * s);
      g = Math.round(0x0b + (0x10 - 0x0b) * s);
      b = Math.round(0x10 + (0x17 - 0x10) * s);
    } else {
      const s = (t - 0.55) / 0.45;
      r = Math.round(0x10 + (0x16 - 0x10) * s);
      g = Math.round(0x10 + (0x16 - 0x10) * s);
      b = Math.round(0x17 + (0x1d - 0x17) * s);
    }
    for (let x = 0; x < gw; x++) {
      const i = (y * gw + x) * 4;
      gdata[i] = r;
      gdata[i + 1] = g;
      gdata[i + 2] = b;
      gdata[i + 3] = 255;
    }
  }
  const gtex = new THREE.DataTexture(gdata, gw, gh, THREE.RGBAFormat);
  gtex.needsUpdate = true;
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({ map: gtex });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;

  // Radial contact shadow
  const shadowGeom = new THREE.CircleGeometry(1.6, 64);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.55,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.35, 0.01);
  shadow.rotation.x = -Math.PI / 2;

  // Lighting setup
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 2);
  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2.5, 1, 1.5);
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);

  // Text rendering via fontAtlas
  const textGroup = new THREE.Group();

  const headline = ctx.fontAtlas.createTextMesh('Calibre NA-01', {
    fontFamily: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: 0xe8ecf2,
  });
  headline.position.set(0, -1.5, 0.1);
  textGroup.add(headline);

  const body = ctx.fontAtlas.createTextMesh('Machined in-house. 41 mm. Grade 5 titanium.', {
    fontFamily: 'JetBrains Mono',
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: 0xe8ecf2,
  });
  body.position.set(0, -1.8, 0.1);
  textGroup.add(body);

  const caption = ctx.fontAtlas.createTextMesh('FROM 4200 USD / SHIPS IN 21 DAYS', {
    fontFamily: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: 0xff2a38,
  });
  caption.position.set(0, -2.0, 0.1);
  textGroup.add(caption);

  // Assemble
  root.add(backdrop);
  root.add(shadow);
  root.add(plinth);
  root.add(keyLight);
  root.add(rimLight);
  root.add(ambientLight);
  root.add(textGroup);

  // Orbit group for continuous rotation
  const orbitGroup = new THREE.Group();
  orbitGroup.add(watch);
  root.add(orbitGroup);

  // Apply cinematic primitives
  ctx.primitives?.orbit?.(orbitGroup, { speed: 0.15, radius: 0.6 });

  // Event handlers
  root.userData.handlers = {
    onPointerEnter: () => {
      ctx.primitives?.['depth-rotate']?.(watch, { maxDeg: 6 });
    },
    onPointerLeave: () => {
      gsap.to(watch.rotation, { x: 0, y: 0, z: 0, duration: 0.9, ease: 'cubic.inOut' });
      gsap.to(watch.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'cubic.inOut' });
    },
  };

  // Cleanup function
  root.userData.cleanup = () => {
    gsap.killTweensOf([watch, watch.rotation, watch.scale]);
    plinthGeom.dispose();
    backdropGeom.dispose();
    shadowGeom.dispose();
    plinthMat.dispose();
    backdropMat.dispose();
    shadowMat.dispose();
    gtex.dispose();
    watch.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return root;
}
